package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamModern43GroupBank2 {
    private const val T = "නූතන බටහිර කලාව හා ශ්‍රී ලංකාවේ '43 කණ්ඩායම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උපස්ථිතිවාදී චිත්‍ර ශිල්පී ක්ලෝඩ් මොනේ එකම ගොඩනැගිල්ලක් හෝ පිදුරු ගොඩක් විවිධ වේලාවලදී කිහිප වරක් සිතුවම් කළේ ඇයි?", "හිරු ආලෝකයේ වෙනස පෙන්වීමට", "පළමු චිත්‍රය අස්ථානගත වූ නිසා", "කැන්වස් විකුණා මුදල් සෙවීමට", "වර්ණ මිශ්‍ර කිරීම අමතක වූ නිසා", "රූවන් දෙව්මැදුර හා පිදුරු ගොඩවල් මාලාවෙන් උදෑසන, දහවල් හා සැඳෑ ආලෝකයේ වෙනස මොනේ පෙන්වීය."),
        q("ජපානයේ සුප්‍රකට සිතුවම් ඇසුරින් 'මේරි කැසැට්' (Mary Cassatt) හා 'බර්ත් මොරිසෝ' (Berthe Morisot) යන කාන්තා උපස්ථිතිවාදී ශිල්පිනියන් වැඩිපුරම සිතුවම් කළේ කුමක්ද?", "මව්වරුන්, දරුවන් සහ එදිනෙදා ගෘහස්ථ ජීවිතයේ සංවේදී අවස්ථා", "ලෝක යුද්ධ සටන් බිම්", "පුරාණ ග්‍රීක දෙවිවරුන්", "කර්මාන්තශාලා යන්ත්‍ර", "19 වන සියවසේ සමාජ සීමා මැද මොරිසෝ හා කැසැට් උපස්ථිතිවාදී කවයේ ප්‍රධාන තැනක් ගත්හ."),
        q("පැරීසියේ රාත්‍රී නර්තන ශාලා (Moulin Rouge) සහ සර්කස් ජවනිකා ලිතොග්‍රැෆි පෝස්ටර් කලාවට ගෙන ආ පශ්චාත් උපස්ථිතිවාදී ශිල්පියා කවුද?", "හෙන්රි ඩි ටූලූස්-ලෝට්‍රෙක්", "ලියනාඩෝ ඩා වින්චි", "ජොටෝ ඩි බොන්ඩෝනේ", "මයිකල් ආන්ජලෝ", "නූතන ග්‍රැෆික් පෝස්ටර් කලාවේ ආරම්භකයෙකු වූ ලෝට්‍රෙක් තද රේඛා හා පැතලි වර්ණ තල යොදා ගත්තේය."),
        q("වින්සන්ට් වෑන් ගෝගේ ප්‍රසිද්ධ 'කැෆේ ටෙරස් ඇට් නයිට්' සහ 'ආර්ල්ස් හි නිදන කාමරය' සිතුවම්වල දැකිය හැකි ප්‍රබල වර්ණ උපක්‍රමය කුමක්ද?", "අනුපූරක වර්ණ එකට ගැටවීම", "තනි කළු හා සුදු වර්ණ පමණක්", "වර්ණ සියල්ල ජලයෙන් සේදීම", "අමු මැටි පමණක් පසුබිමේ ගෑම", "ප්‍රතිවිරුද්ධ උණුසුම් හා සිසිල් වර්ණ එක්ව තැබීමෙන් වෑන් ගෝ අධික චිත්තවේගී තීව්‍රතාවක් මැවීය."),
        q("පෝල් සෙසෑන්ගේ 'ද කාඩ් ප්ලේයර්ස්' සහ නිශ්චල ජීව චිත්‍රවල මේසයේ හෝ පිඟානේ දාරය ඇතැම් විට ඇලවී පෙනෙන්නේ ඇයි?", "කෝණ කිහිපයකින් බලා ඇඳීම නිසා", "රේඛා කෝදුවක් නොතිබූ නිසා", "කැන්වසය තෙතමනයෙන් ඇද වී තිබීම", "වර්ණ ස්තර මිශ්‍ර කිරීමට අපහසු වීම", "සාම්ප්‍රදායික ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණය ඉවත දැමූ සෙසෑන්ගේ මෙම ක්‍රමය කියුබිසම් උපතට හේතු විය."),
        q("කියුබිසම් කලාවේ මුල් අදියර වන 'විශ්ලේෂණාත්මක කියුබිසම්' (Analytical Cubism) හිදී භාවිත කළ වර්ණ මාලාව කෙබඳුද?", "දුඹුරු, අළු වැනි නිහඬ වර්ණ", "දීප්තිමත් නියොන් රෝස හා කොළ", "සම්පූර්ණ දේදුනු වර්ණ හතම", "රන් හා රිදී දිලිසෙන වර්ණ", "වර්ණයට වඩා බහුකෝණී ජ්‍යාමිතික තල විශ්ලේෂණය කෙරෙහි අවධානය යොමු කිරීමට සීමිත වර්ණ යෙදීය."),
        q("1909–1914 කාලයේ ඉතාලියේ බිහි වූ වේගය, යන්ත්‍ර සූත්‍ර, නගර සහ චලනය වන්දනා කළ නූතන කලා ව්‍යාපාරය කුමක්ද?", "අනාගතවාදය (Futurism)", "රොමෑන්ටික්වාදය", "බයිසැන්ටයින් කලාව", "සම්භාව්‍ය ග්‍රීක කලාව", "දුවන බල්ලෙකුගේ පාද බොහෝ ගණනක් පෙන්වන බාලාගේ චිත්‍ර චලන වේගය කැන්වසයට ගෙන ආවේය."),
        q("රුසියානු 'සුප්‍රිමැටිසම්' (Suprematism) ව්‍යාපාරයේ නායක 'කසිමීර් මැලෙවිච්' (Kazimir Malevich) විසින් 1915 දී ඇඳි විප්ලවීය සිතුවම කුමක්ද?", "කළු සමචතුරස්‍රය (Black Square)", "මොනාලිසා", "සූරියකාන්ත මල්", "ඇවිග්නොන් යුවතියෝ", "සුදු පසුබිමක තනි කළු කොටුවක් ඇඳ බාහිර ලෝකය අනුකරණය කිරීමෙන් තොර පිරිසිදු හැඟීම ප්‍රකාශ කළේය."),
        q("ජර්මනියේ 1919 දී වෝල්ටර් ග්‍රෝපියස් ආරම්භ කළ නූතන ගෘහ නිර්මාණ, කලා හා නිර්මාණ පාසල (Art & Design School) කුමක්ද?", "බවුහවුස් (Bauhaus)", "ඇතන්ස් පාසල", "බෙංගාල පාසල", "රාජකීය සිත්තර කුලය", "කලාව, හස්ත කර්මාන්තය හා කාර්මික සැලසුම්කරණය එක් කළ බවුහවුස් නූතන ග්‍රැෆික් හා ගෘහ නිර්මාණයට මුල් විය."),
        q("බවුහවුස් පාසලේ ආචාර්යවරයෙකු වූ ස්විස් ජාතික 'පෝල් ක්ලී' (Paul Klee) චිත්‍ර කලාවේ රේඛාව හැඳින්වූයේ කුමන ප්‍රකට කියමනකින්ද?", "ඇවිදින්නට ගිය තිතකි", "රේඛාව යනු කළු පවුරකි", "වර්ණය යනු අඳුරු අවකාශයකි", "මූර්තිය යනු කඩදාසි කැබැල්ලකි", "ළමා චිත්‍රවල සරල බව හා සංගීත රිද්මය අගය කළ පෝල් ක්ලීගේ චිත්‍ර අතිශය නිර්මාණශීලී වේ."),
        q("වියුක්ත ප්‍රකාශනවාදයේ (Abstract Expressionism) නිශ්චල විශාල වර්ණ ක්ෂේත්‍ර (Color Field Painting) නිර්මාණය කළ ඇමරිකානු ශිල්පියා කවුද?", "මාර්ක් රොත්කෝ (Mark Rothko)", "එඩ්ගා ඩෙගාස්", "රැෆායෙල්", "ඩොනටෙලෝ", "මෘදු දාර සහිත විශාල වර්ණ තීරු මගින් ගැඹුරු භාවනාමය හැඟීම් නරඹන්නා තුළ ඇති කිරීම රොත්කෝගේ අරමුණ විය."),
        q("නූතන මූර්ති කලාවේ ශිලා කුට්ටි මත සිදුරු හා මෘදු වක්‍රාකාර මානව හැඩතල (Negative Space) නෙළූ බ්‍රිතාන්‍ය මූර්ති ශිල්පියා කවුද?", "හෙන්රි මුවර් (Henry Moore)", "මයිරන්", "බර්නිනි", "චෝල ශිල්පීන්", "'සැතපෙන රුව' (Reclining Figure) මාලාවෙන් හෙන්රි මුවර් මූර්තිය තුළ හිස් අවකාශයේ අගය පෙන්වීය."),
        q("පියාසර කරන ස්වාභාවික සමබරතාව සහිත සුළඟින් චලනය වන 'චංචල මූර්ති' (Mobiles / Kinetic Sculpture) නිර්මාණය කළේ කවුද?", "ඇලෙක්සැන්ඩර් කෝල්ඩර්", "මයිකල් ආන්ජලෝ", "ඔගස්ට් රොඩින්", "හෙන්රි මුවර්", "තඹ, වයර් හා තහඩු කැබලි සමතුලිතව එල්ලා චලනය වන මූර්ති කෝල්ඩර් හඳුන්වා දුන්නේය."),
        q("නූතන මූර්ති කලාවේ පියා ලෙස සැලකෙන ප්‍රංශ මූර්ති ශිල්පී 'ඔගස්ට් රොඩින්' (Auguste Rodin) නිර්මාණය කළ ප්‍රකට ලෝකඩ ප්‍රතිමාව කුමක්ද?", "චින්තකයා (The Thinker)", "මයිකල් ආන්ජලෝගේ ඩේවිඩ්", "මයිරන්ගේ ඩිස්කොබොලස්", "වීනස් ඩි මිලෝ ප්‍රතිමාව", "මතුපිට ආලෝකය හා හැඟීම් ප්‍රකාශනය අවධාරණය කළ රොඩින් 19–20 සියවස් මූර්ති විප්ලවය ඇරඹීය."),
        q("රුමේනියානු මූර්ති ශිල්පී 'කොන්ස්ටන්ටින් බ්‍රැන්කුසි' (Constantin Brâncuși) මූර්ති කලාවේදී අනුගමනය කළ විශේෂ ශෛලිය කුමක්ද?", "වස්තුවේ සරල සාරය දැක්වීම", "සෑම සියුම් විස්තරයම කැටයම් කිරීම", "රතු තීන්ත මුළුමනින්ම ආලේප කිරීම", "පුවත්පත් කැබලි ඇලවීමෙන් තැනීම", "බිත්තරයක හෝ අභ්‍යවකාශයේ පියාසර කුරුල්ලෙකුගේ සුමට ආකෘතිය බ්‍රැන්කුසිගේ අවමවාදී ලක්ෂණයයි."),
        q("මෙක්සිකානු චිත්‍ර ශිල්පිනී 'ෆ්‍රීඩා කාලෝ' (Frida Kahlo) ගේ සිතුවම් ලෝක පූජිත වී ඇත්තේ කුමන තේමා නිසාද?", "වේදනාව හා ආත්ම ආලේඛ්‍ය", "වියුක්ත ජ්‍යාමිතික කළු ඉරි", "පෞරාණික රාජකීය යුද ජයග්‍රහණ", "වෙළඳ දැන්වීම් සුප් ටින් රූප", "පුද්ගලික අත්දැකීම් අවංකව හා සංකේතාත්මකව නිරූපණය කිරීම ඇගේ කලාවේ ප්‍රබල ලක්ෂණයකි."),
        q("1960 ගණන්වල බිහි වූ 'ඔප් ආර්ට්' (Op Art - Optical Art) චිත්‍ර කලාවෙන් නරඹන්නා තුළ ඇති කරන ප්‍රධාන බලපෑම කුමක්ද?", "ඇස රවටන දෘෂ්ටි චලන මායාව", "මැටි පෘෂ්ඨ වයන මතු කිරීම", "සිහින ලෝක කතා ඇඳීම", "තෙත් හුණු බදාම සිතුවම් කිරීම", "බ්‍රිජට් රයිලි හා වික්ටර් වසරෙලි ඔප් ආර්ට් මගින් නිශ්චල තලයක කම්පන හා චලන හැඟීම මැවූහ."),
        q("ඡායාරූප කලාව දියුණු වූ පසු 1960–70 දශකවල බිහි වූ 'ෆොටෝ රියලිසම්' (Photorealism) ශෛලියේ විශේෂත්වය කුමක්ද?", "ඡායාරූපයක් සේ සියුම් සිතුවම්", "වියුක්ත රේඛා කිහිපයක් පමණක්", "කැමරාවෙන් මුද්‍රණය කර තැබීම", "පැතලි ඒකවර්ණ පසුබිම් යෙදීම", "චක් ක්ලෝස් හා රිචඩ් එස්ටීස් වැනි ශිල්පීන් ඡායාරූප තරම්ම නිවැරදි සිතුවම් ඇන්දහ."),
        q("වීදි බිත්ති මත ස්ටෙන්සිල් හා ස්ප්‍රේ තීන්ත යොදා සමාජ හා දේශපාලන පණිවිඩ දෙන 'ස්ට්‍රීට් ආර්ට්' (Street Art / Graffiti) නූතන ශිල්පියෙකු කවුද?", "බැන්ක්සි (Banksy) හා කීත් හැරින්ග්", "රැෆායෙල් සන්සියෝ", "ජොටෝ", "දේවරගම්පල හිමි", "පොදු අවකාශයේ බිත්ති කලාගාර බවට පත් කර සමාජ විවේචන ගෙන ඒම සමකාලීන වීදි කලාවේ ලක්ෂණයකි."),
        q("කලාගාරයක මුළු කාමර අවකාශයම ආලෝකය, ශබ්දය හා විවිධ වස්තූන් යොදා ප්‍රේක්ෂකයාට ඇතුළු වී අත්විඳිය හැකි සමකාලීන කලාව කුමක්ද?", "ස්ථාපන කලාව (Installation Art)", "ටෙම්පරා බිතුසිතුවම", "පුස්කොළ පොත් කලාව", "සිල්ක් ස්ක්‍රීන්", "සාම්ප්‍රදායික රාමුගත චිත්‍රය ඉක්මවා ත්‍රිමාණ අවකාශයක් පුරා ප්‍රේක්ෂකයා සම්බන්ධ කර ගැනීමයි."),
        q("ශ්‍රී ලංකාවේ '43 කණ්ඩායමේ පළමු ප්‍රදර්ශනය 1943 නොවැම්බර් මාසයේදී පැවැත්වූයේ කොළඹ කුමන ස්ථානයකද?", "ඩාලි පාරේ (Darley Road) විශේෂ ප්‍රදර්ශන ශාලාවක", "අනුරාධපුර මහමෙව්නාවේ", "සීගිරි ගල මුදුනේ", "ගාල්ල කොටු පවුර මත", "දරුවන්ගේ හා වැඩිහිටියන්ගේ පුරුදු රුචියෙන් ඔබ්බට ගිය නූතන කලා ප්‍රදර්ශනය කොළඹදී පැවැත්විණි."),
        q("'43 කණ්ඩායමේ චිත්‍ර ශිල්පීන් අතර පසුකාලීන ප්‍රදර්ශන සමඟ එක්වූ ප්‍රකට කාන්තා චිත්‍ර ශිල්පිනියක කවුද?", "ඇනට් රොස් (Annette Ross)", "සොලියස් මෙන්ඩිස්", "එල්.ටී.පී. මංජු ශ්‍රී", "ජේ.ඩී.ඒ. පෙරේරා", "ඇනට් ක්ලාක්/රොස් හා ජෝර්ජ් බීවන් වැනි ශිල්පීන් පසුකාලීන කණ්ඩායම සමඟ ප්‍රදර්ශන පැවැත්වූහ."),
        q("ශ්‍රී ලංකාවේ '43 කණ්ඩායමේ සාමාජිකයෙකු වූ 'ඩබ්ලිව්.ජේ.ජී. බෙලින්ග්' (W.J.G. Beling) කලා අධ්‍යාපනයට කළ වැදගත් මෙහෙය කුමක්ද?", "ළමා චිත්‍ර ප්‍රවර්ධනය හා පුහුණුව", "පිටරටින් ප්ලාස්ටික් පිළිම ගෙන ඒම", "දඹුල්ල ලෙන් සුදු හුණු ගෑම", "පරිගණක ග්‍රැෆික් මෘදුකාංග සෑදීම", "ලයනල් වෙන්ඩ්ට් හා ජෝර්ජ් කීට්ගේ සමීප මිතුරෙකු වූ බෙලින්ග් ලාංකේය ළමා චිත්‍ර කලාවට නව ජීවයක් දුන්නේය."),
        q("ජෝර්ජ් කීට් විසින් 'ගෝතමී විහාරයේ' බිතුසිතුවම් ඇඳීමේදී ඔහු අනුගමනය කළ බිත්ති සකස් කිරීමේ මාධ්‍යය කුමක්ද?", "වියළි හුණු බදාමය මත ටෙම්පරා", "දැව පුවරු මත තෙල් සායම්", "පිළිස්සූ මැටි පුවරු ඇලවීම", "ප්ලාස්ටික් ටයිල් මත ඇඳීම", "සම්ප්‍රදායික විහාර චිත්‍ර ක්‍රමයට ගරු කරමින් නූතන රේඛා රටා මගින් බුදු සිරිත ගෝතමී විහාරයේ ඇන්දේය."),
        q("කැලණි විහාරයේ සොලියස් මෙන්ඩිස් මහතා සිතුවම් කළ ප්‍රසිද්ධ ඓතිහාසික දර්ශන අතරින් එකක් නම් කරන්න.", "හේමමාලා හා දන්ත දළදා වැඩමවීම", "මොනාලිසා ආලේඛ්‍ය සිතුවම", "පළමු ලෝක යුද්ධ සටන් බිම", "ගුවර්නිකා ගුවන් බෝම්බ ප්‍රහාරය", "බුද්ධ ශාසන ඉතිහාසයේ සිදුවීම් සොලියස් මෙන්ඩිස් සම්භාව්‍ය පෙරදිග ආභාසයෙන් සිතුවම් කළේය."),
        q("ශ්‍රී ලංකාවේ 'රාජ්‍ය කලායතනය' (වත්මන් සෞන්දර්ය කලා විශ්වවිද්‍යාලය) ආරම්භයේදී වැදගත් කාර්යභාරයක් ඉටු කළ 'ජේ.ඩී.ඒ. පෙරේරා' (J.D.A. Perera) ප්‍රකට වන්නේ කුමන චිත්‍ර සඳහාද?", "ශාස්ත්‍රීය ආලේඛ්‍ය හා භූ දර්ශන", "වියුක්ත කළු ජ්‍යාමිතික රේඛා", "දේශපාලන කාටූන් සිතුවම්", "සමකාලීන වීදි ග්‍රැෆිටි කලාව", "කොළඹ හේවුඩ් කලායතනයේ ප්‍රධානියාව සිටි ජේ.ඩී.ඒ. පෙරේරා විශිෂ්ට තෙල් සායම් ආලේඛ්‍ය ශිල්පියෙකි."),
        q("1950–60 දශකවල ශ්‍රී ලංකාවේ ගැමි හා බෞද්ධ සංස්කෘතික ජීවිතය සරල පැතලි රේඛා හා වර්ණවලින් සිතුවම් කළ 'සරත් සූරසේන / ජී.එස්. ප්‍රනාන්දු' පරපුරේ ජනප්‍රිය ශිල්පියෙකු වූ 'සෝමබන්දු විද්‍යාපති' ප්‍රකට කුමක් සඳහාද?", "වේදිකා රංග වස්ත්‍ර හා සිතුවම්", "රෝම කිරිගරුඬ මූර්ති කැපීම", "කාර්මික ලෝහ යන්ත්‍ර තැනීම", "පුරාවිද්‍යා කැණීම් කටයුතු", "සෝමබන්දු විද්‍යාපති දේශීය සාම්ප්‍රදායික කලා මෝස්තර නූතන නාට්‍ය හා චිත්‍ර කලාවට එක් කළේය."),
        q("ශ්‍රී ලංකාවේ නූතන චිත්‍ර හා සැරසිලි කලාව තුළ 'සරත්චන්ද්‍රගේ මනමේ, සිංහබාහු' වැනි නාට්‍ය සඳහා රංග වස්ත්‍ර හා අංග රචනයෙන් දායක වූ ප්‍රකට ශිල්පියා කවුද?", "සිරි ගුණසිංහ හා සෝමබන්දු", "පැබ්ලෝ පිකාසෝ", "හෙන්රි මුවර්", "ජෝර්ජ් සෝරා", "ලාංකේය නූතන වේදිකාව සාම්ප්‍රදායික කෝලම්, සොකරි හා උඩරට කලා අංගවලින් අලංකාර විය."),
        q("ශ්‍රී ලංකාවේ 'ජාතික කලා පෙරමුණ' හා පසුකාලීන 90 දශකයේ ප්‍රවණතා (90s Trend) නූතන කලාවට ගෙන ආ නව අදහස කුමක්ද?", "සමකාලීන සමාජ, දේශපාලන, යුද හා නාගරික අර්බුද ස්ථාපන, කොලාජ් හා මිශ්‍ර මාධ්‍ය තුළින් ප්‍රකාශ කිරීම", "පැරණි ග්‍රීක දේවාල පමණක් පිටපත් කිරීම", "චිත්‍ර තෙල් සායමට පමණක් සීමා කිරීම", "සියලු චිත්‍ර පන්සල් බිත්තිවල පමණක් ඇඳීම", "චන්ද්‍රගුප්ත තේනුවර, ජගත් වීරසිංහ වැනි ශිල්පීන් 90 දශකයේ සමකාලීන කලා ප්‍රකාශන බිහි කළහ."),
        q("ශ්‍රී ලංකාවේ 90 දශකයේ සමකාලීන කලා ව්‍යාපාරයේ 'බැරලිසම්' (Barrelism) නමැති සංකල්පය හරහා යුද්ධය හා මුරපොළවල් කලාවට ගෙන ආ ශිල්පියා කවුද?", "චන්ද්‍රගුප්ත තේනුවර", "ජෝර්ජ් කීට්", "ලයනල් වෙන්ඩ්ට්", "සොලියස් මෙන්ඩිස්", "ආරක්ෂක බැරල් තේමා කර ගනිමින් ඔහු නිර්මාණය කළ සිතුවම් හා ස්ථාපන ලොව පුරා අවධානය දිනීය."),
        q("ශ්‍රී ලංකාවේ '43 කණ්ඩායමේ ඡායාරූප ශිල්පී ලයනල් වෙන්ඩ්ට්ගේ ඡායාරූප කලාවේ විශේෂත්වය කුමක්ද?", "සෝලරයිසේෂන් හා කළු-සුදු රටා", "වර්ණවත් ඩිජිටල් ඡායාරූප ගැනීම", "පුවත්පත් වෙළඳ දැන්වීම් සැකසීම", "රාමුගත තෙල් සායම් සිතුවම්", "1930–40 දශකවලම ඡායාරූපකරණය උසස් ලලිත කලාවක් බව ලයනල් වෙන්ඩ්ට් ලොවට ඔප්පු කළේය."),
        q("'43 කණ්ඩායමේ සාමාජිකයන්ගෙන් බහුතරය නිරූපණය කළ පොදු දෘෂ්ටිමය ලක්ෂණය කුමක්ද?", "පෞද්ගලික ශෛලීන් ඔස්සේ නිදහස", "සියල්ලන්ම එකම රතු පසුබිමක ඇඳීම", "ගුරුවරයාගේ අණට එකම රූප ඇඳීම", "වර්ණ තුනකට පමණක් සීමා වීම", "කීට්, දැරණියගල, අයිවන් පීරිස්, හැරී පීරිස් යන සෑම කෙනෙකුටම අනන්‍ය පෞද්ගලික ශෛලියක් තිබුණි."),
        q("1948 නිදහස ලැබීමට පෙර 1943 දී '43 කණ්ඩායම බිහි වීම ශ්‍රී ලාංකේය සංස්කෘතියට වැදගත් වන්නේ ඇයි?", "කලාත්මක නිදහස දිනා ගත් බැවින්", "එය බ්‍රිතාන්‍ය රාජ්‍ය සංගමයක් නිසා", "සියලු කලා පාසල් වසා දැමූ නිසා", "පැරණි ග්‍රීක කලාව පිටපත් කළ නිසා", "බටහිර යටත්විජිත මානසිකත්වයෙන් මිදුණු ස්වාධීන සංස්කෘතික පිබිදීමක් මෙයින් ඇති විය."),
        q("නූතන බටහිර කලාවේ 'ඩිජිටල් කලාව' (Digital Art) හා 'මුද්‍රණ ග්‍රැෆික් කලාව' බිහි වීමට පූර්වගාමී වූ 20 වන සියවසේ කලා ව්‍යාපාර මොනවාද?", "බවුහවුස්, පොප් හා සංකල්පීය කලා", "මිසර හා සම්භාව්‍ය ග්‍රීක කලා", "ප්‍රාග් ඓතිහාසික ගල් ගුහා කලාව", "මෞර්ය හා ගුප්ත ශිලා කලාව", "තාක්ෂණය, මුද්‍රණ මාධ්‍ය සහ ජන සංස්කෘතිය කලාව සමඟ බද්ධ වීම අද ඩිජිටල් නිර්මාණකරණයට පදනම දැමීය."),
        q("පැබ්ලෝ පිකාසෝගේ කලා ජීවිතයේ මුල් කාලයේ දුක, දිළිඳු බව හා හුදෙකලාව පෙන්වන වර්ණ යුගය හඳුන්වන්නේ කුමන නමින්ද?", "නිල් යුගය (Blue Period)", "හරිත වර්ණ යුගය", "රන්වන් කහ යුගය", "ඒකවර්ණ අළු යුගය", "තරුණ පිකාසෝ නිල්-කොළ අඳුරු තානයන්ගෙන් මිනිස් දුක සිතුවම් කළ කාලය 'බ්ලූ පීරියඩ්' නම් වේ."),
        q("ලොව පුරා මානව සිරුරු ඉතා සිහින් දිගැති කෙසඟ රූප ලෙස ලෝකඩින් නෙළා මිනිසාගේ හුදෙකලාව පෙන්වූ නූතන මූර්ති ශිල්පියා කවුද?", "ඇල්බර්ටෝ ජියාකොමෙට්ටි", "ග්‍රීක ශිල්පී මයිරන්", "බැරොක් ශිල්පී බර්නිනි", "පුනරුද ශිල්පී ඩොනටෙලෝ", "දෙවන ලෝක යුද්ධයෙන් පසු රළු පෘෂ්ඨයක් ඇති ඉතා සිහින් මිනිස් ප්‍රතිමා ජියාකොමෙට්ටි නිර්මාණය කළේය."),
        q("ශ්‍රී ලංකාවේ දේශීය හා නූතන චිත්‍ර කලාව අතර සමතුලිතතාව රැකගත් 'ස්ටැන්ලි කිරින්දේ' (Stanley Kirinde) විශේෂ වන්නේ කුමක් නිසාද?", "ඉතිහාස කතා හා නිසල රේඛා සංයුති", "පොප් කලා සුප් ටින් ඇඳීම", "වීදුරු මොසැයික් පමණක් කිරීම", "ලෝකඩ ප්‍රතිමා වාත්තු කිරීම", "සිංහල ඉතිහාස හා සාහිත්‍ය අවස්ථා ඉතා සංයමයෙන් හා නිහඬ පැහැදිලි බවකින් ඔහු සිතුවම් කළේය."),
        q("නූතන කලා ලෝකයේ 'කලා කෘතියක අවසන් නිමාවට වඩා කලාකරුවාගේ මූලික අදහසට' (Idea over Object) මුල් තැන දෙන කලා ධාරාව කුමක්ද?", "සංකල්පීය කලාව (Conceptual Art)", "පුනරුද ෆ්‍රෙස්කෝ", "රොමෑන්ටික්වාදය", "නව-සම්භාව්‍යවාදය", "ජෝසප් කොසුත්ගේ 'එකක් සහ පුටු තුනක්' වැනි කෘති හරහා අදහස කලාවේ හරය බව පෙන්වා දෙයි."),
        q("නූතන බටහිර කලාව හා ශ්‍රී ලාංකේය '43 කණ්ඩායම අතර පැවති සම්බන්ධය පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?", "'43 කණ්ඩායම නූතන බටහිර කලා මූලධර්ම දේශීය සංස්කෘතික ආත්මය සමඟ මුසු කළේය", "ඔවුහු නූතන බටහිර කලාව සම්පූර්ණයෙන් ප්‍රතික්ෂේප කළහ", "ඔවුහු පුනරුද චිත්‍ර පිටපත් පමණක් විකුණූහ", "ලංකාවේ චිත්‍ර ශිල්පීන් යුරෝපය ගැන දැන සිටියේ නැත", "පැරීසියේ හා ලන්ඩනයේ කලා ප්‍රවණතා හදාරා එම නිදහස ලාංකේය පරිසරයට ගැළපීම ඔවුන්ගේ ජයග්‍රහණයයි."),
        q("නූතන චිත්‍ර කලාවේ 'මිශ්‍ර මාධ්‍ය' (Mixed Media) යනු කුමක්ද?", "තීන්ත, කඩදාසි, රෙදි එක්ව යෙදීම", "ජල සායම් පමණක් භාවිත කිරීම", "පැන්සල් කූරු පමණක් භාවිත කිරීම", "කළුගලින් පමණක් කැපීම", "කියුබිසම් යුගයෙන් පසු විවිධ ද්‍රව්‍ය එකට ගළපා නව වයන හා අර්ථ මැවීම මිශ්‍ර මාධ්‍ය කලාවේ සිරිතයි.")
    )
}
